StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			SwitchData - Westermo
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			SNMP communication & Westermo Lynx or Redfox                                                                                                                                                                                                                                                                                                                 
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-03-31		William Veim			Initial release      
//	1.1.0				2026-04-09		Ruben Byman			Added various readings and alarms
//	1.1.1				2026-04-14		Ruben Byman			Added ULINT response value
//	1.1.2				2026-04-16		Ruben Byman			Bugfix RSTP OID
//	1.1.3				2026-04-16		Ruben Byman			Bugfix Commstatus
//	1.2.0				2026-04-22		Ruben Byman			Added support for WeOS 4.x.x and increased robustness for differing indexes	
//	1.2.1				2026-04-22		Ruben Byman			Added temperature alarm and changed firmware reading from bootloader to switch family + WeOS version
//	1.2.2				2026-04-22		Ruben Byman			Added error and success counters and error code
//	1.2.3				2026-04-23		Ruben Byman			Changed firmware reading from bootloader to switch family plus WeOS version
//	1.2.4				2026-05-05		Ruben Byman			Added digital input to trigger General Alarm
//	1.2.5				2026-06-09		Ruben Byman			Added retain to prevent resending alarms
//
//===============================================================================================================================
//
//
//===============================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_Swich_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

(*************************************************************************
 *	ASSIGNS TOKEN
 *************************************************************************)
 
IF TokenID = -1 THEN
	FOR TokenID:=0 TO DINT_TO_UINT(UPPER_BOUND(Ext_Telegram.Token_Static, 1)) DO
		IF NOT Ext_Telegram.Token_Static[TokenID] THEN
			Ext_Telegram.Token_Static[TokenID]:=TRUE;
			EXIT;
		END_IF;
	END_FOR;
END_IF;

(*************************************************************************
 *	TIMEOUT (If too long time in state)
 *************************************************************************)
 
IF Ext_Telegram.Token_Active = TokenID THEN
	Wrk_TimeInState:=ADD_TIME(In1:=Wrk_TimeInState, In2:=GetMyTaskInterval());
	IF Wrk_State <> Wrk_SampleState THEN
	Wrk_TimeInState:=TIME#0ms;
	Wrk_SampleState:= Wrk_State;
	END_IF;
ELSE
	Wrk_TimeInState:=TIME#0ms;
	Wrk_State:= 0;
END_IF;

IF Wrk_TimeInState > Ext_Telegram.Timeout THEN
	Wrk_ErrorCode := 16#8000000; // Timeout error code
	Inc(Ext_Telegram.Token_Active);
	Wrk_TimeInState:=TIME#0ms;
END_IF;

(*************************************************************************
 *	CHECKS WHETHER SELECTED PORT FOR TRAFFIC MEASUREMENT WAS CHANGED
 *************************************************************************)
 
IF Ext_Swich_Data.EXT_Statistics.Cfg_TrafficPort <> Wrk_TrafficPortSample THEN
	Wrk_OctetsInSample := 0;
	Wrk_OctetsOutSample := 0;
	Wrk_TrafficPortSample := Ext_Swich_Data.EXT_Statistics.Cfg_TrafficPort;
END_IF;

(*************************************************************************
 *	CHECKS WHETHER A REBOOT HAS HAPPENED
 *************************************************************************)
RE_Reboot(Clk:=(Wrk_Uptime_Raw < 120));

IF RE_Reboot.Q THEN	//Uptime less than 2 minutes
	Wrk_Initialise := FALSE;
END_IF;

(*************************************************************************
 *	CASE FOR REQUEST & DATA SEND
 *************************************************************************)

CASE Wrk_State OF
	
	0: // Wait for turn
		IF Ext_Telegram.Token_Active = TokenID THEN
			
			//Setting common parameters
			Ext_Telegram.RemotePort:=161;
			Ext_Telegram.RemoteIP:=Cfg_IPAdr;
			Ext_Telegram.Community:='public';
			Ext_Telegram.SNMP_Ver:=1;
			IF Wrk_Initialise THEN
				Wrk_State := 10;
			ELSE
				Wrk_State := 1;
			END_IF;
			
		END_IF;
	
	1:	//	Initialize chassis index
		IF NOT Ext_Telegram.Busy THEN
			IF Wrk_ChassisIndex > 1100 THEN
				Wrk_ChassisIndex := 0;
			END_IF;
			Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.47.1.1.1.1.5.', UINT_TO_STRING(In:=Wrk_ChassisIndex));
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 2;
			
		END_IF;
	
	2: // Wait for completion
		IF Ext_Telegram.Done THEN
			IF Ext_Telegram.ResponseValue = 3 THEN	//Found correct index for chassis
				Wrk_State := 3;
			ELSE
				Inc(Wrk_ChassisIndex);
				Wrk_State := 1;
			END_IF;
			
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Inc(Wrk_ChassisIndex);
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	3:	//	Initialize temperature index
		IF NOT Ext_Telegram.Busy THEN
			IF Wrk_TempIndex > 1100 THEN
				Wrk_TempIndex := 0;
			END_IF;
			Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.99.1.1.1.1.', UINT_TO_STRING(In:=Wrk_TempIndex));
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 4;
			
		END_IF;
	
	4: // Wait for completion
		IF Ext_Telegram.Done THEN
			IF Ext_Telegram.ResponseValue = 8 THEN	//Found correct index for temperature
				Wrk_Initialise := TRUE;
				Wrk_State := 10;
			ELSE
				Inc(Wrk_TempIndex);
				Wrk_State := 3;
			END_IF;
			
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Inc(Wrk_TempIndex);
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
	
	10: // Read uptime and checks online status
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.2.1.1.3.0';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 11;
			
		END_IF;
		
	11: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Uptime_Raw := Ext_Telegram.ResponseValue/100;
			Wrk_Status := Ext_Telegram.ResponseValue <> 0;
			Wrk_CommStatus := Ext_Telegram.Comm_OK;
			Wrk_State := 20;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Uptime_Raw:=0;
			Wrk_Status := FALSE;
			Wrk_CommStatus := Ext_Telegram.Comm_OK;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
	
	20: // Read FRNT state
		IF Cfg_FRNT_InUse THEN
			IF NOT Ext_Telegram.Busy THEN
				IF Cfg_FRNT_Version THEN
					Ext_Telegram.OID:='1.3.6.1.4.1.16177.2.5.1.1.1.5.2.1';	//v2 OID
				ELSE
					Ext_Telegram.OID:='1.3.6.1.4.1.16177.2.1.3.3.1.1.1.7.1'; //v0 OID
				END_IF;
				Ext_Telegram.Execute := TRUE;
				Wrk_State := 21;
			END_IF;
		ELSE
			Wrk_State := 30;
		
		END_IF;
				
	21: // Wait for completion
		IF Ext_Telegram.Done THEN
			IF Cfg_FRNT_Version THEN
				Wrk_FRNT_State_Raw := Ext_Telegram.ResponseValue=1;
				Wrk_State := 30;
			ELSE
				Wrk_FRNTv0_Status := Ext_Telegram.ResponseValue;
				Wrk_State := 22;
			END_IF;
			Ext_Telegram.Execute := FALSE;

		ELSIF Ext_Telegram.Error THEN
			Wrk_FRNT_State_Raw:=FALSE;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	22: // Read FRNT focal point (only relevant for FRNT v0)
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.4.1.16177.2.1.3.3.1.1.1.2.1';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 23;
		
		END_IF;
	
	23: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_FRNT_State_Raw := (Ext_Telegram.ResponseValue = Wrk_FRNTv0_Status) AND (Ext_Telegram.ResponseValue <> 0);
			Wrk_State := 30;
			Ext_Telegram.Execute := FALSE;

		ELSIF Ext_Telegram.Error THEN
			Wrk_FRNT_State_Raw:=FALSE;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	30: // Read supply 1 state
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.2.1.99.1.1.1.4.1001';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 31;
			
		END_IF;
		
	31: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Supply1_State_Raw := Ext_Telegram.ResponseValue=1;
			Wrk_State := 40;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Supply1_State_Raw:=FALSE;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
	
	40: // Read supply 2 state
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.2.1.99.1.1.1.4.1002';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 41;
			
		END_IF;
		
	41: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Supply2_State_Raw := Ext_Telegram.ResponseValue=1;
			Wrk_State := 50;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Supply2_State_Raw:=FALSE;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	//States for readings based on specific ports (reading from one port per request cycle)
	50: // Read port states
		IF NOT Ext_Telegram.Busy THEN
			IF Wrk_PortNumber > Cfg_NumOfPorts-1 THEN
				Wrk_PortNumber:=0;
			END_IF;
			
			Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.2.2.1.8.', INT_TO_STRING(In:=Wrk_PortNumber + 4096));
			Ext_Telegram.Execute := TRUE;		
			Wrk_State := 51;
			
		END_IF;
		
	51: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Port_State_Raw[Wrk_PortNumber]:=Ext_Telegram.ResponseValue=1;
			Wrk_State := 60;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Port_State_Raw[Wrk_PortNumber]:=FALSE;
			Inc(Wrk_PortNumber);
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	60: // Read RSTP state
		IF (Wrk_PortNumber = Cfg_RSTP_Port1-1) OR (Wrk_PortNumber = Cfg_RSTP_Port2-1) THEN
			IF NOT Ext_Telegram.Busy THEN
				Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.17.2.15.1.3.', INT_TO_STRING(In:=Wrk_PortNumber + 1));
				Ext_Telegram.Execute := TRUE;
				Wrk_State := 61;
			END_IF;
		ELSE
			Inc(Wrk_PortNumber);
			Wrk_State := 70;
		
		END_IF;
				
	61: // Wait for completion
		IF Ext_Telegram.Done THEN
			IF Wrk_PortNumber = Cfg_RSTP_Port1-1 THEN
				Wrk_RSTP1_State_Raw := UDINT_TO_UINT(Ext_Telegram.ResponseValue);
			ELSIF Wrk_PortNumber = Cfg_RSTP_Port2-1 THEN
				Wrk_RSTP2_State_Raw := UDINT_TO_UINT(Ext_Telegram.ResponseValue);
			END_IF;
			Inc(Wrk_PortNumber);
			Wrk_State := 70;
			Ext_Telegram.Execute := FALSE;

		ELSIF Ext_Telegram.Error THEN
			IF Wrk_PortNumber = Cfg_RSTP_Port1-1 THEN
				Wrk_RSTP1_State_Raw := 0;
			ELSIF Wrk_PortNumber = Cfg_RSTP_Port2-1 THEN
				Wrk_RSTP2_State_Raw := 0;
			END_IF;
			Inc(Wrk_PortNumber);
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	70: // Read temperature
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.99.1.1.1.4.', INT_TO_STRING(In:=Wrk_TempIndex));
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 71;
			
		END_IF;
		
	71: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Temp_Raw := UDINT_TO_INT(Ext_Telegram.ResponseValue);
			Wrk_State := 80;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Temp_Raw:= 0;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;

	80: // Read summary alarm
		IF NOT Ext_Telegram.Busy THEN
			IF Cfg_WeOS_Version THEN
				Ext_Telegram.OID:='1.3.6.1.4.1.16177.2.3.1.2.0';
			ELSE
				Ext_Telegram.OID:='1.3.6.1.4.1.16177.2.1.5.2.1.0';
			END_IF;
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 81;
			
		END_IF;
		
	81: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_SummaryAlarm := Ext_Telegram.ResponseValue <> 1;
			Wrk_State := 90;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_SummaryAlarm:=FALSE;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	90: // Read model
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.47.1.1.1.1.13.', INT_TO_STRING(In:=Wrk_ChassisIndex));
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 91;
			
		END_IF;
		
	91: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Model := Ext_Telegram.ResponseString;
			Wrk_State := 100;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Model:='';
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
	
	100: // Read inbound traffic
		IF Ext_Swich_Data.EXT_Statistics.Cfg_TrafficPort <> 0 THEN
			IF NOT Ext_Telegram.Busy THEN
				Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.31.1.1.1.6.', INT_TO_STRING(In:=Ext_Swich_Data.EXT_Statistics.Cfg_TrafficPort + 4095));
				Ext_Telegram.Execute := TRUE;		
				Wrk_State := 101;
			END_IF;
		ELSE
			Wrk_BitrateIn := 0;
			Wrk_BitrateOut := 0;
			Wrk_State := 120;
			
		END_IF;
		
	101: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_TimestampIn := GetTime();
			IF Ext_Telegram.ResponseValue_64 = 0 THEN
				Wrk_BitrateIn := 0;
			ELSIF Wrk_OctetsInSample = 0 OR Ext_Telegram.ResponseValue_64 < Wrk_OctetsInSample THEN
				Wrk_OctetsInSample := Ext_Telegram.ResponseValue_64;
				Wrk_BitrateIn := 0;
				Wrk_TimestampInSample := Wrk_TimestampIn;
			ELSE
				Wrk_BitrateIn := (ULINT_TO_REAL((Ext_Telegram.ResponseValue_64 - Wrk_OctetsInSample) * 8) / LINT_TO_REAL(TimeToSec(In:=SUB_DT_DT(In1:=Wrk_TimestampIn, In2:=Wrk_TimestampInSample))))/1000;	//Calculated bitrate kb/s
				Wrk_OctetsInSample := Ext_Telegram.ResponseValue_64;
				Wrk_TimestampInSample := Wrk_TimestampIn;
			END_IF;
			Wrk_State := 110;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_BitrateIn := 0;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	110: // Read outbound traffic
		IF Ext_Swich_Data.EXT_Statistics.Cfg_TrafficPort <> 0 THEN
			IF NOT Ext_Telegram.Busy THEN
				Ext_Telegram.OID:=CONCAT('1.3.6.1.2.1.31.1.1.1.10.', INT_TO_STRING(In:=Ext_Swich_Data.EXT_Statistics.Cfg_TrafficPort + 4095));
				Ext_Telegram.Execute := TRUE;		
				Wrk_State := 111;
			END_IF;
		ELSE
			Wrk_BitrateOut := 0;
			Wrk_State := 120;
			
		END_IF;
		
	111: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_TimestampOut := GetTime();
			IF Ext_Telegram.ResponseValue_64 = 0 THEN
				Wrk_BitrateOut := 0;
			ELSIF Wrk_OctetsOutSample = 0 OR Ext_Telegram.ResponseValue_64 < Wrk_OctetsOutSample THEN
				Wrk_OctetsOutSample := Ext_Telegram.ResponseValue_64;
				Wrk_BitrateOut := 0;
				Wrk_TimestampOutSample := Wrk_TimestampOut;
			ELSE
				Wrk_BitrateOut := (ULINT_TO_REAL((Ext_Telegram.ResponseValue_64 - Wrk_OctetsOutSample) * 8) / LINT_TO_REAL(TimeToSec(In:=SUB_DT_DT(In1:=Wrk_TimestampOut, In2:=Wrk_TimestampOutSample))))/1000;	//Calculated bitrate kb/s
				Wrk_OctetsOutSample := Ext_Telegram.ResponseValue_64;
				Wrk_TimestampOutSample := Wrk_TimestampOut;
			END_IF;
			Wrk_State := 120;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_BitrateOut := 0;
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;
		
	120: // Read firmware
		IF NOT Ext_Telegram.Busy THEN
			Ext_Telegram.OID:='1.3.6.1.2.1.1.1.0';
			Ext_Telegram.Execute := TRUE;
			Wrk_State := 121;
			
		END_IF;
		
	121: // Wait for completion
		IF Ext_Telegram.Done THEN
			Wrk_Len := LEN(In:=Ext_Telegram.ResponseString);
			Wrk_Pos := FIND(In1:=Ext_Telegram.ResponseString, In2:=',');
			Wrk_String := DELETE(In:=Ext_Telegram.ResponseString, L:=Wrk_Pos, P:=1);
			Wrk_Pos := Wrk_Pos + FIND(In1:=Wrk_String, In2:=',');
			Wrk_Firmware := DELETE(In:=Ext_Telegram.ResponseString, L:=Wrk_Len-Wrk_Pos+1, P:=Wrk_Pos);	//Extracts string before second comma
			Wrk_State := 1000;
			Ext_Telegram.Execute := FALSE;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_Firmware:='';
			Wrk_State := 1001;
			Ext_Telegram.Execute := FALSE;
			
		END_IF;

	1000: //Completed OK
		Inc(Ext_Telegram.Token_Active);
		Wrk_State := 0;
		Wrk_SNMP_Error :=FALSE;
		Ext_Telegram.Execute := FALSE;
		Wrk_Successes := Wrk_Successes + 1;
	
	1001: //General error
		Inc(Ext_Telegram.Token_Active);
		Wrk_State := 0;
		Wrk_SNMP_Error :=TRUE;
		Wrk_Errors := Wrk_Errors + 1;
		Wrk_ErrorCode := Ext_Telegram.ErrorCode;
		Ext_Telegram.Execute := FALSE;
		
END_CASE;

(*************************************************************************
 *	PERFORMING LOGIC
 *************************************************************************)
//Port status
FOR a := LOWER_BOUND(Wrk_PortStatus, 1) TO UPPER_BOUND(Wrk_PortStatus, 1) DO
	IF a > Cfg_NumOfPorts-1 THEN
		Wrk_PortStatus[a] := -1;
	ELSIF Wrk_Port_State_Raw[a] = TRUE THEN
		Wrk_PortStatus[a] := 1;
	ELSE
		Wrk_PortStatus[a] := 0;
	END_IF;
END_FOR;

//Subring status
IF Cfg_RSTP_Port1 = 0 OR Cfg_RSTP_Port2 = 0 THEN
	Wrk_SubringStatus := -1; //Invisible
ELSIF (Wrk_RSTP1_State_Raw = 2 AND Wrk_RSTP2_State_Raw = 5 AND Wrk_Port_State_Raw[Cfg_RSTP_Port1-1] AND Wrk_Port_State_Raw[Cfg_RSTP_Port2-1]) 			//Port 2 forwarding, Port 1 blocking and link state OK for both ports
	OR (Wrk_RSTP1_State_Raw = 5 AND Wrk_RSTP2_State_Raw = 2 AND Wrk_Port_State_Raw[Cfg_RSTP_Port1-1] AND Wrk_Port_State_Raw[Cfg_RSTP_Port2-1]) THEN	//Port 1 forwarding, Port 2 blocking and link state OK for both ports
	Wrk_SubringStatus := 1;	//OK
ELSE
	Wrk_SubringStatus := 0;	//Error
END_IF;

//Main Ring status
IF NOT Cfg_FRNT_InUse THEN
	Wrk_FRNT_Status := -1;
ELSIF Wrk_FRNT_State_Raw THEN
	Wrk_FRNT_Status := 1;
ELSE
	Wrk_FRNT_Status := 0;
END_IF;

//DC status
IF NOT Cfg_DC2_InUse OR (Wrk_Supply1_State_Raw AND Wrk_Supply2_State_Raw) THEN	//DC2 not in use, or both Power supplies OK
	Wrk_PowerSupply_Fault := FALSE;
ELSE
	Wrk_PowerSupply_Fault := TRUE;
END_IF;

//Communication OK
TOF_CommOK(In:=Wrk_CommStatus, PT:=T#5s);

//Temperature alarm
Wrk_TemperatureAlarm := (Wrk_Temp_Raw > 60);

//General alarm
Wrk_GeneralAlarm := Wrk_SummaryAlarm OR NOT Inp_DigAlarm;

(*************************************************************************
 *	STATE CONFIG INPUT
 *************************************************************************)

Wrk_AlarmState[1]:=		Wrk_FRNT_Status = 0;
IF Cfg_FRNT_InUse THEN
	Wrk_AlarmSuffix[1]:=	'Main Ring Fault';
ELSE
	Wrk_AlarmSuffix[1]:=	'';
END_IF;
Wrk_AlarmState[2]:=		Wrk_SubringStatus = 0;
IF Cfg_RSTP_Port1 <> 0 AND Cfg_RSTP_Port2 <> 0 THEN
	Wrk_AlarmSuffix[2]:=	'Subring Fault';
ELSE
	Wrk_AlarmSuffix[2]:=	'';
END_IF;
Wrk_AlarmState[3]:=		Wrk_GeneralAlarm;
Wrk_AlarmSuffix[3]:=		'General alarm';
Wrk_AlarmState[4]:=		Wrk_SNMP_Error;
Wrk_AlarmSuffix[4]:=		'SNMP Fault';
Wrk_AlarmState[5]:=		Wrk_PowerSupply_Fault;
Wrk_AlarmSuffix[5]:=		'Power Supply Fault';
Wrk_AlarmState[6]:=		NOT TOF_CommOK.Q;
Wrk_AlarmSuffix[6]:=		'Communication Fault';
Wrk_AlarmState[7]:=		Wrk_TemperatureAlarm;
Wrk_AlarmSuffix[7]:=		'High Temperature';
Wrk_AlarmState[8]:=		FALSE;
Wrk_AlarmSuffix[8]:=		'';
Wrk_AlarmState[9]:=		FALSE;
Wrk_AlarmSuffix[9]:=		'';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_Swich_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_Swich_Data.EXT_Engineering, 
						Ext_General:=					Ext_Swich_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_AlarmState, 
						Inp_StateSuffix:=				Wrk_AlarmSuffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING STRUCTURE
 *************************************************************************)
 
 //Block
 Sts_Alarm:=		FB_Data_Logic.Sts_AlarmTriggered;
 
//Common
